    for (let i = 0; i < 25; i++) {
      if (squares[i] === null) {
        isFullBoard = false;
      }
    }
    if (isFullBoard) {
      status = 'Draw';
    } else {
      status = 'Next player: ' + (xIsNext ? 'X' : 'O');
